sys_script_include.script:
var SOWNotifyRequestVisibilitySNC = Class.create();
    SOWNotifyRequestVisibilitySNC.prototype = {
        initialize: function() {},
        CATALOG_REQUEST_ITEM_TABLE: "sc_req_item",
        CATALOG_REQUEST_TABLE: "sc_request",
        CATALOG_TASK_TABLE: "sc_task",
        canShowCallsTab: function(recordSysId, table) {
            if (table === this.CATALOG_REQUEST_ITEM_TABLE || table === this.CATALOG_REQUEST_TABLE || table === this.CATALOG_TASK_TABLE) {
                var gr = new GlideRecordSecure(table);
                if (gr.get(recordSysId) && gr.canWrite())
                    return true;
            }
            return false;
        },
        canShowSendSMS: function(recordSysId, table) {
            if (table === this.CATALOG_REQUEST_ITEM_TABLE || table === this.CATALOG_REQUEST_TABLE || table === this.CATALOG_TASK_TABLE) {
                var gr = new GlideRecordSecure(table);
                if (gr.get(recordSysId) && gr.canWrite())
                    return true;
            }
            return false;
        },
        type: 'SOWNotifyRequestVisibilitySNC'
    };
